import React, { useEffect, useState } from "react";

export default function Table({
  list,
  total,
  shippingAmount = 0.0,
  discountTotal,
  taxTotal,
  netPriceTotal,
}) {
  const [grandTotal, setgrandTotal] = useState(0.0);
  useEffect(() => {
    setgrandTotal(parseFloat(netPriceTotal) + parseFloat(shippingAmount));
  }, [netPriceTotal, shippingAmount]);
  return (
    <>
      <table
        width="100%"
        className="mb-10 my-5 border border-zinc-200 rounded shadow-md p-2"
      >
        <thead>
          <tr className="bg-gray-100 p-1">
            <td className="font-bold">Description</td>
            <td className="font-bold">Unit Price</td>
            <td className="font-bold">Quantity</td>
            <td className="font-bold">Price</td>
            <td className="font-bold">Discount</td>
            <td className="font-bold">Net Amount</td>
          </tr>
        </thead>
        {list.map(
          ({
            id,
            description,
            quantity,
            price,
            discount,
            amount,
            net_amount,
          }) => (
            <React.Fragment key={id}>
              <tbody>
                <tr className="h-10">
                  <td>{description}</td>
                  <td>{price}</td>
                  <td>{quantity}</td>
                  <td>{amount}</td>
                  <td>{discount}</td>
                  <td>{net_amount}</td>
                </tr>
              </tbody>
            </React.Fragment>
          )
        )}
      </table>

      <div className="grid grid-cols-2">
        <div></div>
        <div>
          <div className="grid grid-cols-2 text-gray-800 text-1xl font-semibold">
            <p className="text-left">Shipping Cost KES:</p>{" "}
            <p className="text-right">
              {shippingAmount ? shippingAmount.toLocaleString() : ""}
            </p>
          </div>
          <div className="grid grid-cols-2 text-gray-800 text-1xl font-semibold">
            <p className="text-left">Items Total (KES) :</p>
            <p className="text-right">{total ? total.toLocaleString() : ""}</p>
          </div>
          <div className="grid grid-cols-2 text-gray-800 text-1xl font-semibold">
            <p className="text-left">Total Discount (KES) :</p>
            <p className="text-right">
              {discountTotal ? parseFloat(discountTotal).toFixed(2) : ""}
            </p>
          </div>

          <div className="grid grid-cols-2 text-gray-800 text-1xl font-semibold">
            <p className="text-left">Net Price (KES) :</p>
            <p className="text-right">
              {netPriceTotal ? parseFloat(netPriceTotal).toFixed(2) : ""}
            </p>
          </div>
          <div className="grid grid-cols-2 text-gray-800 text-xl font-semibold">
            <p className="text-left">To Pay (KES) :</p>
            <p className="text-right">
              {grandTotal
                ? parseFloat(grandTotal.toFixed(2).toLocaleString()).toFixed(2)
                : ""}
            </p>
          </div>
        </div>
      </div>
    </>
  );
}
